      //批量
      let selectList = this.items.filter(a => a.check);
      // if (selectList.length == 0) {
      //   this.$alert('请选择至少一条数据', '提示', {confirmButtonText: this.$t("submitText"), cancelButtonText: this.$t("cancelText"), type: "warning"});
